#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_NODES 64
#define NIL -1

static long value[MAX_NODES];
static int left[MAX_NODES];
static int right[MAX_NODES];
static int root = NIL;
static int used = 0;

static void bst_insert(long v)
{
    int idx, cur, parent;
    if (used >= MAX_NODES) return;
    idx = used++;
    value[idx] = v;
    left[idx] = right[idx] = NIL;
    if (root == NIL) { root = idx; return; }
    cur = root;
    while (1) {
        parent = cur;
        if (v < value[cur]) {
            cur = left[cur];
            if (cur == NIL) { left[parent] = idx; return; }
        } else {
            cur = right[cur];
            if (cur == NIL) { right[parent] = idx; return; }
        }
    }
}

static void inorder_traverse(int node, bool *first)
{
    if (node == NIL) return;
    inorder_traverse(left[node], first);
    if (!*first) putchar(' ');
    printf("%ld", value[node]);
    *first = false;
    inorder_traverse(right[node], first);
}

static void preorder_traverse(int node, bool *first)
{
    if (node == NIL) return;
    if (!*first) putchar(' ');
    printf("%ld", value[node]);
    *first = false;
    preorder_traverse(left[node], first);
    preorder_traverse(right[node], first);
}

static void postorder_traverse(int node, bool *first)
{
    if (node == NIL) return;
    postorder_traverse(left[node], first);
    postorder_traverse(right[node], first);
    if (!*first) putchar(' ');
    printf("%ld", value[node]);
    *first = false;
}

int main(int argc, char *argv[])
{
    const char *mode;
    bool first = true;
    int i, limit;
    if (argc < 2) return 0;
    mode = argv[1];
    limit = (argc - 2 > MAX_NODES) ? MAX_NODES : argc - 2;
    for (i = 0; i < limit; ++i) {
        long v = strtol(argv[2 + i], NULL, 10);
        bst_insert(v);
    }
    if (strcmp(mode, "in") == 0) {
        if (root == NIL) {
            puts("EMPTY");
        } else {
            inorder_traverse(root, &first);
            putchar('\n');
        }
    } else if (strcmp(mode, "pre") == 0) {
        preorder_traverse(root, &first);
        putchar('\n');
    } else if (strcmp(mode, "post") == 0) {
        postorder_traverse(root, &first);
        putchar('\n');
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
